}

class Case {
  boolean check(java.util.function.IntPredicate p) { return p.test(1); }
  java.util.function.IntUnaryOperator f(Object o, boolean available) {
    return switch (o) {
      case String s when check(x -> x > 0) && available -> x -> x + s.length();
      default -> x -> x;
    };
  }
  void statement(Object o) {
    switch (o) {
      case String s when check(x -> x > 0) -> System.out.println(s);
      default -> {}
    }
  }
}

class Case {
  record Gate() {}
  boolean check(java.util.function.IntPredicate p) { return p.test(1); }
  int f(Object o) {
    return switch (o) {
      case Gate() when check(x -> x > 0): yield 1;
      default: yield 0;
    };
  }
  void statement(Object o, boolean enabled) {
    switch (o) {
      case String s when (enabled): System.out.println(s); break;
      default: break;
    }
  }
}

class Case {
  static final int KEY = 7;
  enum E { A, B }
  java.util.function.IntSupplier f(int n) {
    return switch (n) {
      case Case.KEY -> () -> 1;
      default -> () -> 0;
    };
  }
  java.util.function.IntUnaryOperator g(E e) {
    return switch (e) {
      case A -> (x) -> x;
      case E.B -> x -> x;
    };
  }
}

class Case {
  static final int KEY = 7;
  interface Curry { java.util.function.IntUnaryOperator apply(int x); }
  Curry f(int n) {
    return switch (n) {
      case KEY -> x -> y -> x + y;
      default -> x -> y -> y;
    };
  }
}

class Case {
  static final int LEFT = 1, RIGHT = 2;
  java.util.function.IntUnaryOperator f(int n) {
    return switch (n) {
      case (3 * LEFT), false ? LEFT : RIGHT -> x -> x + 3;
      default -> x -> 0;
    };
  }
}

