class Case {
  enum Mode { UP, DOWN, KEEP }
  java.util.function.IntUnaryOperator f(Mode mode, boolean positive) {
    return switch (mode) {
      case UP, DOWN -> x -> x - 1;
      case KEEP -> positive ? x -> x + 1 : x -> x;
    };
  }
}

import java.util.function.IntUnaryOperator;
class Case {
  static final int KEY = 3, LIMIT = 4;
  int value;
  IntUnaryOperator f(int n, boolean yes) {
    IntUnaryOperator fn;
    return switch(n) {
      case (int) KEY -> x -> yes ? x+1 : x;
      default -> x -> x;
    };
  }
}

import java.util.function.IntUnaryOperator;
class Case {
  static final int KEY = 3, LIMIT = 4;
